package edu.academic.hotel;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ReservationServiceTest {
 @Mock CustomerRepository customers; @Mock RoomRepository rooms; @Mock BookingRepository bookings; @InjectMocks ReservationService service;
 Room room; LocalDate in,out;
 @BeforeEach void setup(){room=new Room("801","Suite","Bright corner suite",3,"175.50","/suite.jpg","Wi-Fi,King bed");room.id=8L;in=LocalDate.now().plusDays(12);out=in.plusDays(2);}
 BookingRequest request(LocalDate from,LocalDate to,int guests){return new BookingRequest(room.id,"Avery Guest","avery@example.com","555-0111",from,to,guests);}
 @Test void createsCustomerAndRejectsDuplicateEmail(){when(customers.findByEmailIgnoreCase("avery@example.com")).thenReturn(Optional.empty());when(customers.saveAndFlush(any(Customer.class))).thenAnswer(x->x.getArgument(0));CustomerView created=service.createCustomer(new CustomerRequest("Avery Guest","avery@example.com","555-0111"));assertEquals("avery@example.com",created.email());when(customers.findByEmailIgnoreCase("avery@example.com")).thenReturn(Optional.of(new Customer("Avery Guest","avery@example.com","555-0111")));assertEquals(HttpStatus.CONFLICT,assertThrows(ResponseStatusException.class,()->service.createCustomer(new CustomerRequest("Avery Guest","avery@example.com","555-0111"))).getStatusCode());}
 @Test void calculatesTotalOnServerAndCreatesReference(){when(rooms.lockById(room.id)).thenReturn(Optional.of(room));when(rooms.findAvailable(in,out,2,null,null)).thenReturn(List.of(room));when(customers.findByEmailIgnoreCase("avery@example.com")).thenReturn(Optional.empty());when(customers.save(any(Customer.class))).thenAnswer(x->x.getArgument(0));when(bookings.save(any(Booking.class))).thenAnswer(x->x.getArgument(0));BookingView saved=service.book(request(in,out,2));assertEquals(new BigDecimal("351.00"),saved.totalPrice());assertTrue(saved.bookingReference().matches("HR-[A-F0-9]{8}"));assertEquals(BookingStatus.CONFIRMED,saved.bookingStatus());}
 @Test void rejectsOverlapsAndCapacity(){when(rooms.lockById(room.id)).thenReturn(Optional.of(room));when(rooms.findAvailable(in,out,2,null,null)).thenReturn(List.of());assertEquals(HttpStatus.CONFLICT,assertThrows(ResponseStatusException.class,()->service.book(request(in,out,2))).getStatusCode());assertEquals(HttpStatus.BAD_REQUEST,assertThrows(ResponseStatusException.class,()->service.book(request(in,out,4))).getStatusCode());}
 @Test void validatesDateRangeAndRejectsPast(){assertEquals(HttpStatus.BAD_REQUEST,assertThrows(ResponseStatusException.class,()->service.book(request(in,in,1))).getStatusCode());assertEquals(HttpStatus.BAD_REQUEST,assertThrows(ResponseStatusException.class,()->service.book(request(LocalDate.now().minusDays(1),in,1))).getStatusCode());verifyNoInteractions(rooms,customers,bookings);}
 @Test void cancellationPersistsStatusAndRejectsDuplicateCancellation(){Booking b=new Booking();b.bookingReference="HR-TEST1234";b.bookingStatus=BookingStatus.CONFIRMED;b.customer=new Customer("Avery","avery@example.com","555");b.room=room;when(bookings.findByBookingReference(b.bookingReference)).thenReturn(Optional.of(b));BookingView cancelled=service.cancel(b.bookingReference);assertEquals(BookingStatus.CANCELLED,cancelled.bookingStatus());assertEquals(BookingStatus.CANCELLED,b.bookingStatus);assertEquals(HttpStatus.CONFLICT,assertThrows(ResponseStatusException.class,()->service.cancel(b.bookingReference)).getStatusCode());}
 @Test void availableSearchUsesRequestedRangeAndGuestCount(){when(rooms.findAvailable(in,out,2,"Suite",null)).thenReturn(List.of(room));List<RoomView> result=service.available(in,out,2,"Suite");assertEquals(1,result.size());verify(rooms).findAvailable(in,out,2,"Suite",null);}
}


